"""Camera restoration comparison page; originals are never overwritten."""
HTML = r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>PalmIR 掌纹恢复</title><style>
*{box-sizing:border-box}body{margin:0;background:#f3f5f7;color:#17212b;font:16px system-ui,sans-serif}
header,main{max-width:1080px;margin:auto;padding:20px}header{display:flex;justify-content:space-between;align-items:center;gap:16px}
h1{font-size:24px}h2{font-size:18px}a{color:#125e9c}.card{background:white;border:1px solid #dce2e8;border-radius:12px;padding:20px;margin-bottom:16px}
#view{position:relative;background:#141b22;line-height:0;max-width:720px;margin:auto}#camera{width:100%;height:auto}#box{position:absolute;border:2px solid #6effb1;pointer-events:none}
.controls{display:flex;flex-wrap:wrap;gap:20px;margin:18px 0}label{display:flex;align-items:center;gap:8px}input{max-width:150px}
button{background:#12624c;color:white;border:0;border-radius:8px;padding:12px 18px;font:inherit;cursor:pointer}button:disabled{opacity:.5}
.pair{display:grid;grid-template-columns:1fr 1fr;gap:20px}.pair img{width:100%;max-width:320px;image-rendering:auto;border-radius:8px;background:#ddd}
.muted{color:#546576;line-height:1.6}#status{white-space:pre-wrap}figure{margin:0}figcaption{margin-bottom:10px}#results[hidden]{display:none}
</style><header><h1>PalmIR 掌纹恢复</h1><span><a href="/palmir-report">历史图片测试与示例</a> · <a href="/collect">返回原图采集</a></span></header><main>
<section class="card"><h2>选择掌心区域</h2><p>把掌心放在绿框内。可点击画面移动选框，或用滑块调整；先拍摄并固定原图，再在图上选框。</p>
<p id="focusStatus" class="muted">正在检查自动对焦…</p><button id="focus" disabled>启用连续自动对焦</button><p class="muted">先保持掌心不动，等待画面清晰后再拍摄。自动对焦开启不代表每张照片都已合焦。</p>
<div id="view"><img id="camera" alt="实时摄像头画面"><div id="box"></div></div>
<div class="controls"><label>横向<input id="x" type="range" min="0" max="100" value="50"></label><label>纵向<input id="y" type="range" min="0" max="100" value="50"></label><label>范围<input id="size" type="range" min="10" max="100" value="50"></label></div>
<button id="snapshot">拍摄原图 / 重新拍摄</button> <button id="reference" disabled>设为参考掌纹</button> <button id="run" disabled>恢复选定掌心区域</button><p id="status" role="status">先拍摄原图，再选择掌心区域</p>
<p id="compareStatus" class="muted">可先设置一张参考掌纹，再重新拍摄同一只手，比较恢复前后的 DoN 匹配距离。距离越低表示越相似；尚未校准通过阈值，不能据此计算通过率。</p>
<p id="qualityStatus" class="muted">低对比或阴影不等于模糊；优先改善光照、对焦和掌心定位。当前模型在某些模糊条件下也可能降低识别成功率。</p>
<p class="muted">使用本地训练的 PalmIR 风格 RIA 模型。输入为手动选择的 128 × 128 掌心区域；不自动定位掌纹，也不进行身份判断。当前摄像头上的恢复效果尚未验证。</p></section>
<section class="card" id="results" hidden><h2>同一次拍摄的恢复对比</h2><div class="pair"><figure><figcaption>恢复前 · 128 × 128</figcaption><img id="original" alt="恢复前掌心区域"><p><a id="downloadOriginal" download="palm-original.png">下载输入图</a></p></figure><figure><figcaption>模型恢复后 · 128 × 128</figcaption><img id="restored" alt="恢复后掌心区域"><p><a id="downloadRestored" download="palm-restored.png">下载恢复图</a></p></figure></div><p><a id="downloadSource" download="palm-source.png">下载本次完整原图</a></p><p class="muted">图片只在本次页面中保留；需要保存请下载。模型可能改变掌纹细节，原始采集数据不会被覆盖。</p></section></main>
<script>
const camera=document.getElementById('camera'),box=document.getElementById('box'),view=document.getElementById('view');
const focusStatus=document.getElementById('focusStatus'),focusButton=document.getElementById('focus');
async function checkFocus(method='GET'){try{const r=await fetch('/api/camera/focus',{method,headers:method==='POST'?{'Content-Type':'application/json'}:{},body:method==='POST'?'{}':undefined});const d=await r.json();focusStatus.textContent=d.supported?(d.continuous?'连续自动对焦已开启':'摄像头支持自动对焦，当前已关闭'):'当前摄像头未提供可用的自动对焦控制';focusButton.disabled=!d.supported;}catch(e){focusStatus.textContent='自动对焦状态暂时不可用'}}focusButton.onclick=()=>checkFocus('POST');checkFocus();
const x=document.getElementById('x'),y=document.getElementById('y'),size=document.getElementById('size'),run=document.getElementById('run'),status=document.getElementById('status'),snapshot=document.getElementById('snapshot');const reference=document.getElementById('reference'),compareStatus=document.getElementById('compareStatus');let busy=false,snapshotId=null;
function draw(){let w=camera.clientWidth,h=camera.clientHeight,s=Math.min(w,h)*size.value/100;box.style.width=s+'px';box.style.height=s+'px';box.style.left=Math.min(w-s,Math.max(0,w*x.value/100-s/2))+'px';box.style.top=Math.min(h-s,Math.max(0,h*y.value/100-s/2))+'px'}
[x,y,size].forEach(el=>el.oninput=draw);window.addEventListener('resize',draw);camera.onload=()=>{draw();setTimeout(poll,250)};camera.onerror=()=>setTimeout(poll,1000);
function poll(){if(snapshotId)return;if(!busy)camera.src='/frame.jpg?t='+Date.now();else setTimeout(poll,250)}poll();
view.onclick=e=>{const r=camera.getBoundingClientRect();x.value=Math.round(100*(e.clientX-r.left)/r.width);y.value=Math.round(100*(e.clientY-r.top)/r.height);draw()};
snapshot.onclick=async()=>{busy=true;snapshot.disabled=true;run.disabled=true;status.textContent='正在拍摄原图…';try{const r=await fetch('/api/palmir/snapshot',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});const d=await r.json();if(!r.ok)throw Error(d.message||'拍摄失败');snapshotId=d.snapshot_id;camera.src=d.source;document.getElementById('results').hidden=true;status.textContent='已固定本次原图。点击掌心并调整绿框，再点击恢复。'}catch(e){status.textContent='未完成：'+e.message}finally{busy=false;snapshot.disabled=false;run.disabled=!snapshotId;reference.disabled=!snapshotId}};
reference.onclick=async()=>{reference.disabled=true;try{const r=await fetch('/api/palmir/reference',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({snapshot_id:snapshotId,x:x.value/100,y:y.value/100,size:size.value/100})});const d=await r.json();if(!r.ok)throw Error(d.message||'设置失败');compareStatus.textContent='已设置参考掌纹。请重新拍摄，选取同一掌心区域后恢复比较。'}catch(e){compareStatus.textContent=e.message}finally{reference.disabled=false}};
run.onclick=async()=>{busy=true;run.disabled=true;snapshot.disabled=true;reference.disabled=true;status.textContent='正在恢复…';try{const r=await fetch('/api/palmir/restore',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({snapshot_id:snapshotId,x:x.value/100,y:y.value/100,size:size.value/100})});const d=await r.json();if(!r.ok)throw Error(d.message||'恢复失败');for(const id of ['original','restored']){document.getElementById(id).src=d[id];document.getElementById('download'+id[0].toUpperCase()+id.slice(1)).href=d[id]}if(d.don_comparison){const c=d.don_comparison;compareStatus.textContent=d.same_as_reference?'这是参考图本身，请重新拍摄后比较。':`DoN 匹配距离（越低越好）：恢复前 ${c.raw_distance.toFixed(5)} / 恢复后 ${c.restored_distance.toFixed(5)} / 改善 ${c.improvement>=0?'+':''}${c.improvement.toFixed(5)}。此为分数比较，不是通过率。`}if(d.input_quality){const q=d.input_quality;document.getElementById('qualityStatus').textContent=`输入对比度 ${q.contrast.toFixed(1)}。`+(q.low_contrast_warning?'低于工程提醒值 12，建议补光或调整姿势后重拍；不自动剔除测试样本。':'此数值不能保证掌心定位正确。')}document.getElementById('downloadSource').href=d.source;document.getElementById('results').hidden=false;status.textContent=`恢复完成 · 模型推理 ${d.inference_ms} ms · 输入 ${d.input_size} × ${d.input_size} · 原图 ${d.source_size.join(' × ')}`;}catch(e){status.textContent='未完成：'+e.message}finally{busy=false;run.disabled=false;snapshot.disabled=false;reference.disabled=false}};
</script></html>'''
